/**
 * Wildfire: how long it lasts at a Flame Bot level, and the amplification it gives.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    getWildfireDuration, getWildfireAmplification
 * depends    src/mechanics/combat/types, src/mechanics/primitives/constants
 * used by    src/calculators/specs.generated, src/mechanics/bots/medal-plus-effects, src/mechanics/combat/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { WILDFIRE_DURATION_LEVEL_SCALE, WILDFIRE_DURATION_OFFSET } from '../primitives/constants'
import type { WildfireAmplificationInput } from './types'

export function getWildfireDuration(botLevel: number): number {
  return Math.max(0, botLevel) * WILDFIRE_DURATION_LEVEL_SCALE + WILDFIRE_DURATION_OFFSET
}

export function getWildfireAmplification(input: WildfireAmplificationInput): number {
  if (input.wildfireActive && input.statMult != null) {
    return input.statBase * input.statMult
  }
  return input.statBase
}
